"use client"

import * as React from "react"
import { Avatar as AvatarPrimitive } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { avatarRingRecipe } from "@/lib/ink/recipes/avatar-ink"
import { cn } from "@/lib/utils"

function Avatar({
  className,
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Root> & { seed?: string | number }) {
  const { hostRef, hostProps, node } = useInk({
    recipe: avatarRingRecipe,
    params: {},
    kind: "avatar",
    seed,
    still: true,
  })

  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      ref={useMergedRef<HTMLSpanElement>(hostRef, ref)}
      {...hostProps}
      className={cn("relative isolate flex size-10 shrink-0 overflow-hidden rounded-full", className)}
      {...props}
    >
      {node}
      {children}
    </AvatarPrimitive.Root>
  )
}

function AvatarImage({ className, ref, ...props }: React.ComponentProps<typeof AvatarPrimitive.Image>) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      ref={ref}
      className={cn("relative z-[1] aspect-square size-full object-cover", className)}
      {...props}
    />
  )
}

function AvatarFallback({ className, ref, ...props }: React.ComponentProps<typeof AvatarPrimitive.Fallback>) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      ref={ref}
      className={cn(
        "relative z-[1] flex size-full items-center justify-center rounded-full bg-[color-mix(in_srgb,var(--sd-sand-slip)_55%,transparent)] text-sm font-medium text-foreground",
        className,
      )}
      {...props}
    />
  )
}

export { Avatar, AvatarFallback, AvatarImage }

import { wash } from '@/lib/ink/fills'
import { pillPoly } from '@/lib/ink/geom'
import { loop } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export const avatarRingRecipe = defineRecipe<Record<string, never>>({
  id: 'avatar-ring',
  kind: 'avatar',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w, h }) {
    const d = Math.min(w, h)
    const cx = w / 2
    const cy = h / 2
    const outer = d / 2 - 0.65
    const inner = outer - 2.4
    const body = pillPoly(cx - outer, cy - outer, outer * 2, outer * 2)

    ink.layer('rest', () => {
      softFill(ink, body, [
        { color: 'sand-slip', alpha: 0.35, wobble: 0.42 },
        { color: 'sand', alpha: 0.18, inset: 0.8 },
      ])
      wash(ink, body, 'sand-shade', { alpha: 0.12, material: 'wash', wobble: 0.35, inset: 1.2 })
      loop(ink, cx, cy, outer, outer, {
        pen: 'rose.fine',
        clean: true,
        opts: { alpha: 0.62, simple: true, wobble: 0.28 },
      })
      loop(ink, cx, cy, inner, inner, {
        pen: 'pencil.fine',
        clean: true,
        opts: { alpha: 0.4, simple: true, color: 'line-soft' },
      })
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
